{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "This bill would change a grade-level dividing line in Tennessee Code Annotated, Section 49-6-3402, which is part of the law on student discipline. Wherever the section now says \"grades one through six (1-6),\" it would say \"grades one through five (1-5).\"",
      "rationale": "Identifies the amended section and conveys the replacement of every reference to grades 1–6 with grades 1–5."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "Wherever it now says \"grades seven through twelve (7-12),\" it would say \"grades six through twelve (6-12).\"",
      "rationale": "Conveys the replacement of every reference to grades 7–12 with grades 6–12 in the previously identified Section 49-6-3402."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "The act would take effect as soon as it becomes law.",
      "rationale": "Accurately conveys that the act takes effect upon becoming law."
    }
  ]
}
